/// <reference types="vite/client" />
import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import "./index.css";
import App from "./App";

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <App />
  </StrictMode>
);

/**
 * Offline support. `public/sw.js` is generated by `scripts/build-sw.mjs` at the
 * end of every production build. Registration is production-only so the Vite
 * dev server is never shadowed by a stale worker, and deferred until the load
 * event so precaching never competes with the first paint's requests.
 */
if (import.meta.env.PROD && "serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("/sw.js").catch((error: unknown) => {
      // Offline support is an enhancement: a failed registration must never break the app.
      console.warn("Paperly offline support is unavailable:", error);
    });
  });
}
